    source_code: '#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <deque>\n\nusing namespace std;\n\nconst long long INF = 1e18;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n, m, k;\n    if (!(cin >> n >> m >> k)) return 0;\n\n    vector<long long> A(n + 1);\n    for (int i = 1; i <= n; i++) {\n        cin >> A[i];\n    }\n\n    vector<long long> dp(n + 1, -INF);\n    dp[0] = 0;\n\n    long long global_ans = -INF;\n\n    for (int j = 1; j <= k; j++) {\n        vector<long long> next_dp(n + 1, -INF);\n        deque<int> q;\n\n        for (int i = 1; i <= n; i++) {\n            int new_k = i - 1;\n            if (dp[new_k] != -INF) {\n                while (!q.empty() && dp[q.back()] <= dp[new_k]) {\n                    q.pop_back();\n                }\n                q.push_back(new_k);\n            }\n\n            while (!q.empty() && q.front() < i - m - 1) {\n                q.pop_front();\n            }\n\n            if (!q.empty()) {\n                next_dp[i] = dp[q.front()] + A[i];\n            }\n        }\n\n        dp = move(next_dp);\n\n        for (int i = max(0, n - m); i <= n; i++) {\n            if (dp[i] > global_ans) {\n                global_ans = dp[i];\n            }\n        }\n    }\n\n    if (global_ans <= -INF / 2) {\n        cout << -1 << "\\n";\n    } else {\n        cout << global_ans << "\\n";\n    }\n\n    return 0;\n}',
